import re

def validate_sunroof_state(value):
    """Validate sunroof state value"""
    if isinstance(value, (int, float)):
        # Check gear range
        if 0 <= value <= 10:
            return True, "Valid gear range"
        return False, f"Gear out of range: {value}"

    elif isinstance(value, str):
        # Check percentage
        try:
            pct = float(value)
            if 0 <= pct <= 100:
